contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(address caller, address account, bytes32 role) public {
        vm.assume(caller != account);
        vm.assume(!c.hasRole(role, account));

        vm.prank(caller);
        bool reverted;
        try c.renounceRole(role, account) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assertTrue(reverted);
    }
}
